 for (aid,n),tokens in CLAUSES.items():
  if any(t not in sources[aid]['selected_pages'][str(n)]for t in tokens):raise ValueError('fifteenth four risk/remediation clause changed')
 for q in p['cross_sources']:
  if q['key']not in CROSS_SOURCE_BINDINGS or {k:q.get(k)for k in CROSS_SOURCE_BINDINGS[q['key']]}!=CROSS_SOURCE_BINDINGS[q['key']]:raise ValueError('thirteenth cross source binding changed')
 audit=fifteenth_quote_audit(p['cross_sources'],fresh)
 from st_regime_comparison import build
